from uuid import UUID

from fastapi import HTTPException
from pydantic import HttpUrl
from sqlmodel import Session

from app.brand.api.schemas import BrandGetResponse, BrandPostRequest, BrandPostResponse
from app.brand.db.models import Brand


class BrandServicer:
    def create_brand(
        self, brand_post_request: BrandPostRequest, session: Session
    ) -> BrandPostResponse:
        brand = Brand(
            url=str(brand_post_request.url) if brand_post_request.url else None,
            docs=brand_post_request.docs,
        )
        session.add(brand)
        session.commit()
        session.refresh(brand)
        return BrandPostResponse(
            id=brand.id,
            url=HttpUrl(brand.url) if brand.url else None,
            docs=brand.docs,
        )

    def get_brand(self, brand_id: UUID, session: Session) -> BrandGetResponse:
        brand = session.get(Brand, brand_id)
        if brand is None:
            raise HTTPException(status_code=404, detail="Brand not found")
        return BrandGetResponse(
            url=HttpUrl(brand.url) if brand.url else None,
            docs=brand.docs,
            id=brand.id,
        )

from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Depends
from sqlmodel import Session

from app.base.api.dependencies import get_session
from app.brand.api.schemas import BrandGetResponse, BrandPostRequest, BrandPostResponse
from app.brand.api.servicer import BrandServicer

router = APIRouter(
    prefix="/brands",
)


@router.post("/")
def create_brand(
    brand: BrandPostRequest, session: Annotated[Session, Depends(get_session)]
) -> BrandPostResponse:
    servicer = BrandServicer()
    return servicer.create_brand(brand, session)


@router.get("/{brand_id}")
def get_brand(
    brand_id: UUID, session: Annotated[Session, Depends(get_session)]
) -> BrandGetResponse:
    servicer = BrandServicer()
    return servicer.get_brand(brand_id, session)
